#include <iostream>
#include <vector>
#include <utility>

using namespace std;

int main() {
    int n;
    cin >> n;

    int upper = 0, lower = 0;
    bool canSwap = false;

    for (int i = 0; i < n; ++i) {
        int a, b;
        cin >> a >> b;

        upper += a;
        lower += b;

        if ((a % 2) != (b % 2))
            canSwap = true;
    }

    if (upper % 2 == 0 && lower % 2 == 0)
        cout << 0;
    else if (upper % 2 == 1 && lower % 2 == 1 && canSwap)
        cout << 1;
    else
        cout << -1;

    return 0;
}

